fn run_targeted<const L: usize>(p: u32, terms: &[&str], expect: &str) -> bool
where
    Wide<L>: SupportedWidth,
{
    let mut c = ctx::<L>(p);
    let mut sum = ExactWideSum::new();
    let mut refused = None;
    for t in terms {
        if let Err(r) = add_term(&mut sum, &mut c, t) {
            refused = Some(r);
            break;
        }
    }
    let got = match refused {
        Some(r) => r,
        None => match sum.round(&mut c) {
            Ok(v) => {
                assert_eq!(tok(&v), expect, "p {p} terms {terms:?}");
                if expect == "Z+" {
                    assert!(!v.is_sign_negative(), "exact zero must be +0");
                }
                return true;
            }
            Err(r) => r,
        },
    };
    let expected = match expect {
        "refuse:span" => SumRefusal::Span,
        "refuse:exponent" => SumRefusal::Exponent,
        other => panic!("p {p} terms {terms:?}: refused {got:?}, expected {other}"),
    };
    assert_eq!(got, expected, "p {p} terms {terms:?}");
    false
}

// ---------------------------------------------------------------- tokens

/// `Z+`, `Z-`, or `<sign><hex>p<e>`: the significand's hex digits from the
/// top, left-aligned to 64L bits, and the exponent of the leading bit.
pub(crate) fn parse<const L: usize>(token: &str) -> Wide<L>
where
    Wide<L>: SupportedWidth,
{
    match token {
        "Z+" => return Wide::<L>::ZERO,
        "Z-" => return Wide::<L>::ZERO.neg(),
        _ => {}
    }
    let negative = match &token[..1] {
        "+" => false,
        "-" => true,
        other => panic!("bad sign {other} in {token}"),
    };
    let (hex, exponent) = token[1..].split_once('p').expect(token);
    assert!(!hex.is_empty() && hex.len() <= 16 * L, "{token}");
    let mut significand = [0u64; L];
    for k in 0..L {
        let start = (16 * k).min(hex.len());
        let end = (16 * k + 16).min(hex.len());
        let mut digits = hex[start..end].to_string();
        while digits.len() < 16 {
            digits.push('0');
        }
        significand[L - 1 - k] = u64::from_str_radix(&digits, 16).expect(token);
    }
    Wide::<L>::from_parts(negative, exponent.parse().expect(token), significand).expect(token)
}

pub(crate) fn tok<const L: usize>(w: &Wide<L>) -> String
where
    Wide<L>: SupportedWidth,
{
    let (negative, exponent, significand) = w.parts();
    if w.is_zero() {
        return if negative { "Z-" } else { "Z+" }.to_string();
    }
    let mut hex = String::new();
    for limb in significand.iter().rev() {
        hex.push_str(&format!("{limb:016x}"));
    }
    let sign = if negative { '-' } else { '+' };
    format!("{sign}{}p{exponent}", hex.trim_end_matches('0'))
}

/// K3's record encoding of a value: sign, exponent (LE), limbs (LE).

def sum_targeted():
    lines = []

    def emit(p, L, terms, expect):
        # terms: list of (token, (m, e)); expect: W or "refuse:<why>"
        toks = " ".join(t for t, _ in terms)
        res = expect if isinstance(expect, str) else expect.token()
        lines.append("sum %d %d %d %s = %s" % (L, p, len(terms), toks, res))

    def W_(L, neg, m, lsb):
        return W.from_int(L, neg, m, lsb)

    def wt(w, negate=False):
        return (("~" if negate else "") + "w:" + w.token(),
                (lambda me: (-me[0], me[1]) if negate else me)(w_exact(w)))

    def ft(x, negate=False):
        me = f_exact(x)
        return (("~" if negate else "") + "f:" + hexf(x), (-me[0], me[1]) if negate else me)

    def xt(a, b, negate=False):
        ma, ea = w_exact(a)
        mb, eb = w_exact(b)
        me = (ma * mb, ea + eb)
        return (("~" if negate else "") + "x:" + a.token() + "*" + b.token(),
                (-me[0], me[1]) if negate else me)

    def it(neg, mag, e, negate=False):
        me = (-mag if neg else mag, e)
        return (("~" if negate else "") + "i:" + tok_int(neg, mag, e),
                (-me[0], me[1]) if negate else me)

    def expect(terms, p, L):
        return round_exact(exact_sum([me for _, me in terms]), p, L)

    precisions = list(K4_PRECISIONS) + [(255, 4), (511, 8), (1023, 16)]
    # RV12's counterexample (p = 128): 1 + 2^-127, 2^-128, -2^-400 -> 1 + 2^-127.
    L = 4
    t = [wt(W_(L, False, (1 << 127) + 1, -127)), wt(W_(L, False, 1, -128)), wt(W_(L, True, 1, -400))]
    e = expect(t, 128, L)
    assert e.frac() == 1 + Fr(1, 1 << 127)
    emit(128, L, t, e)
    for p, L in precisions:
        one = W_(L, False, 1, 0)
        ulp = Fr(1, 1 << (p - 1))
        # Ties decided by a far tail: big (even or odd last bit) + half ulp +- far.
        for odd in (0, 1):
            big = W_(L, False, (1 << (p - 1)) + odd, -(p - 1))
            half = W_(L, False, 1, -p)
            for far_exp in (-p - 5, -p - 64, -p - 300, -p - 2000, -64 * L - 1, -64 * L - 2):
                for fneg in (False, True):
                    far = W_(L, fneg, 1, far_exp)
                    t = [wt(big), wt(half), wt(far)]
                    emit(p, L, t, expect(t, p, L))
            # the exact tie (no tail): ties to even
            t = [wt(big), wt(half)]
            emit(p, L, t, expect(t, p, L))

fn add_raw(&mut self, negative: bool, t: &[u64], lsb: i128) -> Result<(), SumRefusal> {
    let (Some(lo), Some(hi)) = (lowest_bit(t), highest_bit(t)) else {
        return Ok(());
    };
    let term_low = lsb + lo as i128;
    let term_high = lsb + hi as i128;
    let (new_low, new_high) = if self.empty {
        (term_low, term_high)
    } else {
        (self.anchor.min(term_low), self.high.max(term_high))
    };
    let span = new_high - new_low + 1;
    if span > SPAN_LIMIT_BITS {
        return Err(SumRefusal::Span);
    }
    if self.empty {
        self.anchor = new_low;
        self.used = 0;
        self.empty = false;
    } else if new_low < self.anchor {
        let shift = (self.anchor - new_low) as usize;
        self.shift_up(shift);
        self.anchor = new_low;
    }
    self.high = new_high;
    self.work.max_span_bits = self.work.max_span_bits.max(span as u64);
    // The term with its low zero bits removed (bits above `hi` are zero, so

    /// The netted exact value: (negative, magnitude, used limbs, anchor).
    fn net(&mut self) -> (bool, Magnitude, usize) {
        let used = self.used;
        self.work.net_limbs += 2 * used as u64;
        let (negative, big, small) = match compare(&self.positive[..used], &self.negative[..used]) {
            Ordering::Less => (true, &self.negative, &self.positive),
            _ => (false, &self.positive, &self.negative),
        };
        let mut out = [0u64; SUM_LIMBS];
        let mut borrow = false;
        for i in 0..used {
            let (x, b1) = big[i].overflowing_sub(small[i]);
            let (y, b2) = x.overflowing_sub(u64::from(borrow));
            out[i] = y;
            borrow = b1 || b2;
        }
        debug_assert!(!borrow);
        (negative, out, used)
    }

    /// The exact value rounded once to the context's precision (nearest, ties
    /// to even); an exact zero is +0.
    pub(crate) fn round<const L: usize>(
        &mut self,
        context: &mut WideContext<L>,
    ) -> Result<Wide<L>, SumRefusal>
    where
        Wide<L>: SupportedWidth,
    {
        if self.empty {
            return Ok(context.from_integer(false, &[0], 0)?);
        }
        let (negative, magnitude, used) = self.net();
        let anchor = i64::try_from(self.anchor).map_err(|_| SumRefusal::Exponent)?;
        self.work.rounded_limbs += used as u64;
        Ok(context.from_integer(negative, &magnitude[..used.max(1)], anchor)?)
    }
}

